CREATE TEMP TABLE before_404_heroes ON COMMIT DROP AS
SELECT x.*,to_jsonb(p) before_values FROM repair_404_heroes x
JOIN public.products p ON p.id=x.website_id AND p.image_url=x.image_url
JOIN tj.aiq_products t ON t.id=x.pim_id AND t.model=x.model
JOIN tj.pim_product_images i ON i.id=x.image_id AND i.product_id=t.id AND i.cdn_url=x.replacement
WHERE x.primary_status=404 AND i.approved AND tj_private.pim_web_verified_image_url(i,t.model)
AND tj_private.pim_web_image_appliance(t) AND p.brand_canonical_id=public.brand_resolve(t.brand_name)
AND p.category=tj_private.pim_web_category(t.category) AND p.status NOT IN ('hidden','archived');
UPDATE public.products p SET image_url=b.replacement,write_source='pim_catalog_completion'
FROM before_404_heroes b WHERE p.id=b.website_id;
DO $check$ BEGIN
IF EXISTS(SELECT 1 FROM before_404_heroes b JOIN public.products p ON p.id=b.website_id
WHERE (b.before_values - ARRAY['image_url','write_source','updated_at']) IS DISTINCT FROM
(to_jsonb(p) - ARRAY['image_url','write_source','updated_at']))
THEN RAISE EXCEPTION 'Unexpected non-photo catalog change'; END IF;
END $check$;
INSERT INTO tj_private.pim_web_completion_log(organization_id,pim_product_id,website_product_id,source_updated_at,action,before_values,after_values,detail)
SELECT b.organization_id,b.pim_id,b.website_id,i.updated_at,'repaired_broken_primary',b.before_values,to_jsonb(p),
jsonb_build_object('operation','repair_ten_confirmed_404_primary_photos','old_http_status',404,'replacement_http_status',200,'exact_model',b.model,'pim_image_id',b.image_id,'checked_on','2026-10-11','manufacturer_attestation',false,'source_and_existing_gallery_preserved',true)
FROM before_404_heroes b JOIN public.products p ON p.id=b.website_id JOIN tj.pim_product_images i ON i.id=b.image_id;
SELECT count(*) repaired_primary_photos FROM before_404_heroes;
COMMIT;
